/** Proyección a `RouteObject[]` (react-router) — solo las rutas con `Component` ya generado;
 * las verbatim (`Component: null`, aún sin convertir) las resuelve el propio App.tsx/kit. */
export function toRouteObjects(rs: AppRoute[] = routes): RouteObject[] {
  return rs.filter((r): r is AppRoute & { Component: ComponentType } => r.Component !== null).map((r) => ({ path: r.path, Component: r.Component }));
}

/** A visitor who already has a session (e.g. the preview's "Signed in as" just opened one) leaves the sign-in form. */
function SignedInRedirect(props: { to: string; children: ReactNode }) {
  const { identity, pending } = useIdentity();
  if (pending) return <LoadingFallback />;
  if (identity !== null) return <Navigate to={props.to} replace />;
  return <>{props.children}</>;
}
